# JARVIS Morning Briefing v2.7
# İzmir hava durumu + haftalık özet + müzik önerisi
# API anahtarı gerektirmez: Open-Meteo public endpoint
# ═════════════════════════════════════════════════════════════

IZMIR_LAT = 38.4237
IZMIR_LON = 27.1428

WEATHER_CODE_TR = {
    0: "Açık",
    1: "Genellikle açık",
    2: "Parçalı bulutlu",
    3: "Bulutlu",
    45: "Sisli",
    48: "Kırağılı sis",
    51: "Hafif çisenti",
    53: "Çisenti",
    55: "Yoğun çisenti",
    56: "Hafif donan çisenti",
    57: "Donan çisenti",
    61: "Hafif yağmur",
    63: "Yağmur",
    65: "Kuvvetli yağmur",
    66: "Hafif donan yağmur",
    67: "Donan yağmur",
    71: "Hafif kar",
    73: "Kar",
    75: "Kuvvetli kar",
    77: "Kar taneleri",
    80: "Kısa süreli sağanak",
    81: "Sağanak",
    82: "Kuvvetli sağanak",
    85: "Hafif kar sağanağı",
    86: "Kuvvetli kar sağanağı",
    95: "Gök gürültülü",
    96: "Dolu ihtimalli gök gürültülü",
    99: "Kuvvetli dolu ihtimalli gök gürültülü",
}

DAY_TR_SHORT = ["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"]

def _safe_url_json(url: str, timeout: int = 8) -> dict:
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "JARVIS-local-assistant/2.7",
            "Accept": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        return json.loads(raw)

def _weather_desc(code) -> str:
    try:
        return WEATHER_CODE_TR.get(int(code), f"Kod {code}")
    except Exception:
        return "Bilinmiyor"

def _build_weekly_weather_rows(daily: dict) -> list:
    times = daily.get("time", []) or []
    highs = daily.get("temperature_2m_max", []) or []
    lows = daily.get("temperature_2m_min", []) or []
    codes = daily.get("weather_code", []) or []

    rows = []
    for i, day_iso in enumerate(times[:7]):
        try:
            d = date.fromisoformat(day_iso)
            label = DAY_TR_SHORT[d.weekday()]
        except Exception:
            label = day_iso

        high = highs[i] if i < len(highs) else None
        low = lows[i] if i < len(lows) else None
        code = codes[i] if i < len(codes) else None

        rows.append({
            "day": label,
            "date": day_iso,
            "high": round(float(high)) if high is not None else None,
            "low": round(float(low)) if low is not None else None,
            "desc": _weather_desc(code),
            "code": code,
        })
    return rows

def get_izmir_weather_briefing() -> dict:
    params = urllib.parse.urlencode({
        "latitude": IZMIR_LAT,
        "longitude": IZMIR_LON,
        "current": "temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m",
        "daily": "weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",
        "timezone": "Europe/Istanbul",
        "forecast_days": 7,
    })
    url = f"https://api.open-meteo.com/v1/forecast?{params}"
    data = _safe_url_json(url)

    current = data.get("current", {}) or {}
    daily = data.get("daily", {}) or {}
    rows = _build_weekly_weather_rows(daily)

    temp = current.get("temperature_2m")
    apparent = current.get("apparent_temperature")
    humidity = current.get("relative_humidity_2m")
    wind = current.get("wind_speed_10m")
    desc = _weather_desc(current.get("weather_code"))

    today = rows[0] if rows else {}
    rain_days = [r for r in rows if any(word in (r.get("desc") or "").lower() for word in ["yağmur", "sağanak", "gök", "çisenti"])]
    hot_days = [r for r in rows if (r.get("high") is not None and r["high"] >= 30)]

    weekly_text = " ".join(
        f"{r['day']} {r['high'] if r['high'] is not None else '-'}°"
        for r in rows
    )

    notes = []
    if today.get("high") is not None:
        if today["high"] >= 30:
            notes.append("Bugün sıcaklık yüksek; dışarı çıkacaksanız su ve gölge protokolünü ciddiye alalım.")
        elif today["high"] <= 15:
            notes.append("Bugün serin görünüyor; ince hesap kadar ince giyinmemek mantıklı olur.")
        else:
            notes.append("Bugün hava çalışmak ve plan yapmak için makul görünüyor.")
    if rain_days:
        notes.append(f"Yağış ihtimali olan günler var: {', '.join(r['day'] for r in rain_days[:3])}. Motosiklet planı varsa kontrol etmenizi öneririm.")
    if hot_days:
        notes.append(f"Hafta içinde sıcak günler öne çıkıyor: {', '.join(r['day'] for r in hot_days[:3])}.")

    return {
        "ok": True,
        "source": "Open-Meteo",
        "location": "İzmir",
        "current": {
            "temperature": round(float(temp)) if temp is not None else None,
            "apparent_temperature": round(float(apparent)) if apparent is not None else None,
            "humidity": humidity,
            "wind": wind,
            "desc": desc,
        },
        "today": today,
        "weekly": rows,
        "weekly_text": weekly_text,
        "notes": notes,
    }

def build_music_briefing() -> dict:
    # Spotify entegrasyonu v5 aşamasında OAuth ile bağlanacak.
    # Şimdilik kullanıcının rock/AC-DC eğilimine göre yerel öneri motoru.
    suggestions = [
        {"mood": "Sabah başlatma", "artist": "AC/DC", "track": "Back in Black", "reason": "Kontrol paneli hazırsa giriş de iddialı olmalı."},
        {"mood": "Odak", "artist": "AC/DC", "track": "Shoot to Thrill", "reason": "Enerjiyi yükseltir, sistemi fazla dağıtmaz."},
        {"mood": "Gece çalışma", "artist": "AC/DC", "track": "Hells Bells", "reason": "Geç saat için dramatik; yani maalesef size uygun."},
        {"mood": "Motosiklet öncesi", "artist": "AC/DC", "track": "Highway to Hell", "reason": "Başlık yüzünden değil, ritim yüzünden. Hız kısmını lütfen mecazi tutalım."},
        {"mood": "Kısa güç modu", "artist": "AC/DC", "track": "Thunderstruck", "reason": "Abartılı olabilir; bu yüzden tam yerinde."},
    ]
    hour = datetime.now().hour
    if hour < 11:
        pick = suggestions[0]
    elif hour < 18:
        pick = suggestions[1]
    elif hour < 23:
        pick = suggestions[3]
    else:
        pick = suggestions[2]
    return {
        "ok": True,
        "spotify_connected": False,
        "status": "Spotify OAuth bağlantısı v5 aşamasında bağlanacak.",
        "suggestion": pick,
        "library_hint": "Spotify bağlandığında beğenilen şarkılar, çalma listeleri ve AC/DC/rock ağırlığına göre seçim yapılacak.",
    }

def build_morning_briefing() -> dict:
    now = datetime.now()
    weather = None
    weather_error = None
    try:
        weather = get_izmir_weather_briefing()
    except Exception as e:
        weather_error = str(e)
        weather = {
            "ok": False,
            "location": "İzmir",
            "current": {},
            "today": {},
            "weekly": [],
            "weekly_text": "",
            "notes": ["Hava durumu servisine ulaşamadım. Bağlantı tarafında küçük bir itaatsizlik var efendim."],
        }

    music = build_music_briefing()

    temp = weather.get("current", {}).get("temperature")
    desc = weather.get("current", {}).get("desc") or "hava durumu alınıyor"
    today = weather.get("today", {}) or {}
    high = today.get("high")
    low = today.get("low")

    greeting = "Günaydın efendim" if now.hour < 11 else ("Hoş geldiniz efendim" if now.hour < 22 else "İyi geceler efendim")

    weather_sentence = f"İzmir şu an {desc.lower()}"
    if temp is not None:
        weather_sentence += f", {temp} derece"
    weather_sentence += "."
    if high is not None:
        weather_sentence += f" Bugün {high} dereceye kadar çıkması bekleniyor"
        if low is not None:
            weather_sentence += f"; gece {low} derece civarı"
        weather_sentence += "."

    music_pick = music.get("suggestion", {})
    briefing_text = (
        f"{greeting}. {weather_sentence} "
        f"{' '.join(weather.get('notes', [])[:2])} "
        f"Müzik tarafında {music_pick.get('artist', 'rock')} - {music_pick.get('track', 'uygun bir parça')} öneriyorum. "
        f"{music_pick.get('reason', '')}"
    ).strip()

    return {
        "ok": True,
        "ts": now.isoformat(),
        "title": "Sabah Brifingi",
        "briefing": briefing_text,
        "weather": weather,
        "weather_error": weather_error,
        "music": music,
    }




# ═════════════════════════════════════════════════════════════
# JARVIS v3 — Koruma Kalkanı / gerçek güvenlik modülü
# - Login ekranı
# - PBKDF2 şifre hash
# - Session cookie
# - IP bazlı başarısız giriş sayacı
# - 5 hatada geçici IP blok
# - Erişim logları
# - Ngrok/dış bağlantı farkındalığı
# - Güvenli mod altyapısı
# ═════════════════════════════════════════════════════════════

SECURITY_DB = Path("memory/jarvis_security.db")
SECURITY_DB.parent.mkdir(exist_ok=True)

SESSION_COOKIE = "jarvis_session"
SESSION_MAX_AGE = 60 * 60 * 12  # 12 saat
MAX_FAILED_ATTEMPTS = 5
BLOCK_SECONDS = 15 * 60

JARVIS_PASSWORD_HASH = os.environ.get("JARVIS_PASSWORD_HASH", "").strip()
JARVIS_SESSION_SECRET = os.environ.get("JARVIS_SESSION_SECRET", "").strip()
COOKIE_SECURE = os.environ.get("JARVIS_COOKIE_SECURE", "0").lower() in ("1", "true", "yes", "on")
SAFE_MODE = os.environ.get("JARVIS_SAFE_MODE", "0").lower() in ("1", "true", "yes", "on")

PUBLIC_PATH_PREFIXES = (
    "/login",
    "/favicon.ico",
    "/healthz",
)

def _sec_conn():
    c = sqlite3.connect(str(SECURITY_DB))
    c.row_factory = sqlite3.Row
    return c

def _init_security_db():
    c = _sec_conn()
    c.execute("""
        CREATE TABLE IF NOT EXISTS security_settings(
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS sessions(
            token TEXT PRIMARY KEY,
            ip TEXT,
            user_agent TEXT,
            created_at REAL,
            expires_at REAL,
            last_seen REAL
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS login_attempts(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts REAL,
            ip TEXT,
            user_agent TEXT,
            success INTEGER,
            reason TEXT
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS ip_blocks(
            ip TEXT PRIMARY KEY,
            blocked_until REAL,
            reason TEXT,
            attempts INTEGER,
            updated_at REAL
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS access_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            ts REAL,
            ip TEXT,
            method TEXT,
            path TEXT,
            user_agent TEXT,
            authed INTEGER,
            external INTEGER,
            note TEXT
        )
    """)
    c.commit()

    # A3: Artık varsayılan "jarvis" şifresinden otomatik hash üretilmez.
    # Şifre setup_password.py ile .env içindeki JARVIS_PASSWORD_HASH üzerinden yönetilir.
    if JARVIS_PASSWORD_HASH:
        c.execute(
            "INSERT OR REPLACE INTO security_settings(key,value) VALUES('password_hash', ?)",
            (JARVIS_PASSWORD_HASH,)
        )
        c.execute("INSERT OR REPLACE INTO security_settings(key,value) VALUES('initialized_at', ?)", (str(time.time()),))
        c.commit()
    c.close()

_init_security_db()

def _client_ip(request: Request) -> str:
    forwarded = request.headers.get("x-forwarded-for") or request.headers.get("x-real-ip")
    if forwarded:
        return forwarded.split(",")[0].strip()
    if request.client:
        return request.client.host
    return "unknown"

def _is_private_ip(ip: str) -> bool:
    if ip in ("127.0.0.1", "::1", "localhost", "unknown"):
        return True
    if ip.startswith("192.168.") or ip.startswith("10."):
        return True
    if ip.startswith("172."):
        try:
            second = int(ip.split(".")[1])
            return 16 <= second <= 31
        except Exception:
            return False
    return False

def _is_external_request(request: Request, ip: str) -> bool:
    host = (request.headers.get("host") or "").lower()
    proto = (request.headers.get("x-forwarded-proto") or "").lower()
    via = (request.headers.get("via") or "").lower()
    if "ngrok" in host or "ngrok" in via:
        return True
    if proto in ("https", "http") and not _is_private_ip(ip):
        return True
    return not _is_private_ip(ip)

def _get_password_hash() -> str | None:
    if JARVIS_PASSWORD_HASH:
        return JARVIS_PASSWORD_HASH

    c = _sec_conn()
    row = c.execute("SELECT value FROM security_settings WHERE key='password_hash'").fetchone()
    c.close()

    if not row:
        return None
    return row["value"]

def _verify_password(password: str) -> bool:
    stored_hash = _get_password_hash()
    if not stored_hash:
        return False

    try:
        scheme, iter_s, salt, expected = stored_hash.split("$", 3)
        if scheme not in ("pbk2_sha256", "pbkdf2_sha256"):
            return False
        digest = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), int(iter_s)).hex()
        return hmac.compare_digest(digest, expected)
    except Exception:
        return False

def _is_blocked(ip: str):
    now = time.time()
    c = _sec_conn()
    row = c.execute("SELECT blocked_until, reason, attempts FROM ip_blocks WHERE ip=?", (ip,)).fetchone()
    if row and float(row["blocked_until"]) > now:
        c.close()
        return True, float(row["blocked_until"]), row["reason"], row["attempts"]
    if row:
        c.execute("DELETE FROM ip_blocks WHERE ip=?", (ip,))
        c.commit()
    c.close()
    return False, 0, "", 0

def _recent_failed_count(ip: str, window_seconds: int = BLOCK_SECONDS) -> int:
    since = time.time() - window_seconds
    c = _sec_conn()
    row = c.execute(
        "SELECT COUNT(*) AS n FROM login_attempts WHERE ip=? AND success=0 AND ts>=?",
        (ip, since)
    ).fetchone()
    c.close()
    return int(row["n"] if row else 0)

def _log_login_attempt(ip: str, user_agent: str, success: bool, reason: str):
    c = _sec_conn()
    c.execute(
        "INSERT INTO login_attempts(ts, ip, user_agent, success, reason) VALUES(?,?,?,?,?)",
        (time.time(), ip, user_agent, int(success), reason)
    )
    c.commit()
    c.close()

def _block_ip(ip: str, reason: str):
    attempts = _recent_failed_count(ip, BLOCK_SECONDS)
    c = _sec_conn()
    c.execute(
        "INSERT OR REPLACE INTO ip_blocks(ip, blocked_until, reason, attempts, updated_at) VALUES(?,?,?,?,?)",
        (ip, time.time() + BLOCK_SECONDS, reason, attempts, time.time())
    )
    c.commit()
    c.close()

def _create_session(ip: str, user_agent: str) -> str:
    token = secrets.token_urlsafe(32)
    now = time.time()
    c = _sec_conn()
    c.execute(
        "INSERT INTO sessions(token, ip, user_agent, created_at, expires_at, last_seen) VALUES(?,?,?,?,?,?)",
        (token, ip, user_agent, now, now + SESSION_MAX_AGE, now)
    )
    c.commit()
    c.close()
    return token

def _session_valid(token: str | None, request: Request) -> bool:
    if not token:
        return False
    now = time.time()
    c = _sec_conn()
    row = c.execute("SELECT expires_at FROM sessions WHERE token=?", (token,)).fetchone()
    if not row:
        c.close()
        return False
    if float(row["expires_at"]) < now:
        c.execute("DELETE FROM sessions WHERE token=?", (token,))
        c.commit()
        c.close()
        return False
    c.execute("UPDATE sessions SET last_seen=? WHERE token=?", (now, token))
    c.commit()
    c.close()
    return True

def _log_access(request: Request, authed: bool, note: str = ""):
    try:
        ip = _client_ip(request)
        c = _sec_conn()
        c.execute(
            "INSERT INTO access_logs(ts, ip, method, path, user_agent, authed, external, note) VALUES(?,?,?,?,?,?,?,?)",
            (
                time.time(),
                ip,
                request.method,
                request.url.path,
                request.headers.get("user-agent", ""),
                int(authed),
                int(_is_external_request(request, ip)),
                note,
            )
        )
        c.commit()
        c.close()
    except Exception:
        pass


def _security_phrase(level: str, failed_24h: int, blocked_list: list, external: bool, ip: str) -> str:
    if blocked_list:
        b = blocked_list[0]
        return (
            f"Beşinci hatalı denemenin ardından {b['ip']} adresini geçici olarak engelledim efendim. "
            "Kapıyı yüzlerine kapattım diyebiliriz."
        )
    if failed_24h >= 4:
        return (
            f"Kontrol paneline yönelik ardışık hatalı girişler devam ediyor beyefendi. "
            f"Son 24 saatte {failed_24h} başarısız deneme kaydettim; kaynağı sessizce izliyorum."
        )
    if failed_24h >= 3:
        return (
            "Aynı erişim hattından üçüncü kez hatalı şifre denemesi gerçekleşti efendim. "
            "İşlem kayıtlarını Koruma Kalkanı kartınıza yansıtıyorum."
        )
    if failed_24h >= 1:
        return (
            "Sisteme başarısız bir giriş denemesi yapıldı efendim. "
            "Şifre hatalı girildi; ilgili IP adresini sessizce izlemeye aldım."
        )
    if external:
        return (
            "Efendim, dış bağlantı hattı açık görünüyor. "
            "Sizin yetkilendirmediğiniz trafiği giriş ekranında tutuyorum."
        )
    return "Koruma Kalkanı aktif. Erişim yerel hatta ve oturum kontrolü altında."

def _security_status(request: Request | None = None) -> dict:
    now = time.time()
    c = _sec_conn()

    failed_total = c.execute("SELECT COUNT(*) AS n FROM login_attempts WHERE success=0").fetchone()["n"]
    failed_24h = c.execute("SELECT COUNT(*) AS n FROM login_attempts WHERE success=0 AND ts>=?", (now - 86400,)).fetchone()["n"]
    blocked = c.execute("SELECT ip, blocked_until, reason, attempts FROM ip_blocks WHERE blocked_until>?", (now,)).fetchall()
    last_fail = c.execute("SELECT ts, ip, reason FROM login_attempts WHERE success=0 ORDER BY ts DESC LIMIT 1").fetchone()
    last_external = c.execute("SELECT ts, ip, path FROM access_logs WHERE external=1 ORDER BY ts DESC LIMIT 1").fetchone()
    sessions = c.execute("SELECT COUNT(*) AS n FROM sessions WHERE expires_at>?", (now,)).fetchone()["n"]
    c.close()

    ip = _client_ip(request) if request else "unknown"
    external = _is_external_request(request, ip) if request else False
    host = (request.headers.get("host") if request else "") or ""
    ngrok_open = "ngrok" in host.lower() or external

    blocked_list = [
        {
            "ip": r["ip"],
            "remaining_seconds": max(0, int(float(r["blocked_until"]) - now)),
            "reason": r["reason"],
            "attempts": r["attempts"],
        }
        for r in blocked
    ]

    recent_unknown_ip = last_external["ip"] if last_external else "Yok"

    if blocked_list:
        level = "alarm"
    elif failed_24h >= 3:
        level = "warning"
    elif external:
        level = "watch"
    else:
        level = "normal"

    jarvis_line = _security_phrase(level, failed_24h, blocked_list, external, ip)

    return {
        "enabled": True,
        "auth_required": True,
        "safe_mode": SAFE_MODE,
        "access_scope": "Dış bağlantı / Ngrok" if ngrok_open else "Yerel",
        "ngrok_open": ngrok_open,
        "current_ip": ip,
        "recent_unknown_ip": recent_unknown_ip,
        "failed_total": failed_total,
        "failed_24h": failed_24h,
        "blocked_ips": blocked_list,
        "active_sessions": sessions,
        "last_failed": dict(last_fail) if last_fail else None,
        "level": level,
        "jarvis_line": jarvis_line,
        "max_failed_attempts": MAX_FAILED_ATTEMPTS,
        "block_minutes": int(BLOCK_SECONDS / 60),
        "biometric_status": "Hazırlık",
        "voice_id_ready": False,
        "face_id_ready": False,
    }

@app.middleware("http")
async def jarvis_security_middleware(request: Request, call_next):
    path = request.url.path
    ip = _client_ip(request)
    user_agent = request.headers.get("user-agent", "")

    # Login sayfası ve favicon public kalır.
    if path.startswith(PUBLIC_PATH_PREFIXES):
        response = await call_next(request)
        _log_access(request, authed=False, note="public")
        return response

    blocked, until, reason, attempts = _is_blocked(ip)
    if blocked:
        _log_access(request, authed=False, note="blocked")
        if path.startswith("/api/") or path.startswith("/ws/"):
            return JSONResponse(
                {
                    "ok": False,
                    "error": "IP geçici olarak kilitli.",
                    "blocked_until": until,
                    "jarvis": f"Efendim, {ip} adresini geçici olarak kilitledim. Tekrarlayan yetkisiz denemeler tespit edildi.",
                },
                status_code=403,
            )
        return RedirectResponse(url="/login?blocked=1", status_code=303)

    token = request.cookies.get(SESSION_COOKIE)
    authed = _session_valid(token, request)

    if not authed:
        _log_access(request, authed=False, note="auth_required")
        if path.startswith("/api/") or path.startswith("/ws/") or path in ("/chat", "/speak", "/transcribe", "/upload_doc"):
            return JSONResponse({"ok": False, "error": "Oturum gerekli."}, status_code=401)
        return RedirectResponse(url="/login", status_code=303)

    response = await call_next(request)
    _log_access(request, authed=True, note="ok")
    return response


