@app.get("/login", response_class=HTMLResponse)
async def login_page(request: Request):
    ip = _client_ip(request)
    blocked, until, reason, attempts = _is_blocked(ip)
    error = ""
    if request.query_params.get("blocked"):
        mins = max(1, int((until - time.time()) / 60))
        error = f"IP geçici olarak kilitlendi. Yaklaşık {mins} dakika sonra tekrar deneyin."
    elif request.query_params.get("err"):
        left = max(0, MAX_FAILED_ATTEMPTS - _recent_failed_count(ip, BLOCK_SECONDS))
        error = f"Erişim reddedildi. Kalan deneme: {left}"
    return HTMLResponse(LOGIN_UI.replace("{error}", error))

@app.post("/login")
async def login_submit(request: Request, password: str = Form(...)):
    ip = _client_ip(request)
    ua = request.headers.get("user-agent", "")

    blocked, until, reason, attempts = _is_blocked(ip)
    if blocked:
        _log_login_attempt(ip, ua, False, "blocked")
        return RedirectResponse(url="/login?blocked=1", status_code=303)

    if _verify_password(password):
        _log_login_attempt(ip, ua, True, "ok")
        token = _create_session(ip, ua)
        response = RedirectResponse(url="/", status_code=303)
        response.set_cookie(
            SESSION_COOKIE,
            token,
            max_age=SESSION_MAX_AGE,
            httponly=True,
            samesite="lax",
            secure=COOKIE_SECURE,
        )
        return response

    _log_login_attempt(ip, ua, False, "wrong_password")
    failed = _recent_failed_count(ip, BLOCK_SECONDS)
    if failed >= MAX_FAILED_ATTEMPTS:
        _block_ip(ip, "too_many_failed_logins")
        return RedirectResponse(url="/login?blocked=1", status_code=303)

    return RedirectResponse(url="/login?err=1", status_code=303)

@app.get("/logout")
async def logout(request: Request):
    token = request.cookies.get(SESSION_COOKIE)
    if token:
        c = _sec_conn()
        c.execute("DELETE FROM sessions WHERE token=?", (token,))
        c.commit()
        c.close()
    response = RedirectResponse(url="/login", status_code=303)
    response.delete_cookie(SESSION_COOKIE)
    return response

