# ════════════════════════════════════════════════════
# A) WebSocket Streaming
# ════════════════════════════════════════════════════
@app.websocket("/ws/chat")
async def websocket_chat(ws: WebSocket):
    # A2: WebSocket auth kontrolü.
    # FastAPI HTTP middleware WebSocket handshake'i korumaz; cookie burada ayrıca doğrulanır.
    token = ws.cookies.get(SESSION_COOKIE)
    if not _session_valid(token, None):
        try:
            await ws.accept()
            await ws.close(code=1008)
        except Exception:
            pass
        return

    await ws.accept()
    try:
        while True:
            data = await ws.receive_json()
            msg = data.get("message", "").strip()
            if not msg:
                continue

            # Brain'in tam mantığını kullanmak için chat() çağırıp
            # cevabı kelime kelime gönder (semi-streaming).
            # to_thread: Ollama beklerken FastAPI event loop kilitlenmesin.
            import asyncio
            full_response = await asyncio.to_thread(brain.chat, msg)
            if not isinstance(full_response, str) or not full_response.strip():
                full_response = "Efendim, beyin modülü boş cevap döndürdü. Faz 1 güvenlik sigortası devreye girdi."

            # Kelime kelime gönder
            words = full_response.split()
            for i, w in enumerate(words):
                await ws.send_json({
                    "type":    "token",
                    "content": w + (" " if i < len(words)-1 else ""),
                })
                import asyncio
                await asyncio.sleep(0.04)  # Akış efekti

            await ws.send_json({
                "type": "done",
                "name": brain.profile.get("name", "Kullanıcı"),
                "turn": getattr(brain, 'turn_count', 0),
            })
    except WebSocketDisconnect:
        pass
    except Exception as e:
        try:
            await ws.send_json({"type": "error", "content": str(e)})
        except:
            pass


